FILES = json.loads('{"custom_components/ha_panel/__init__.py": "\\"\\"\\"A configurable panel shared by dashboard cards and small MQTT displays.\\"\\"\\"\\nfrom homeassistant.const import Platform\\n\\nPLATFORMS = [Platform.SENSOR]\\n\\n\\nasync def async_setup_entry(hass, entry):\\n    await hass.config_entries.async_forward_entry_setups(entry, PLATFORMS)\\n    entry.async_on_unload(entry.add_update_listener(_reload))\\n    return True\\n\\n\\nasync def _reload(hass, entry):\\n    await hass.config_entries.async_reload(entry.entry_id)\\n\\n\\nasync def async_unload_entry(hass, entry):\\n    return await hass.config_entries.async_unload_platforms(entry, PLATFORMS)\\n", "custom_components/ha_panel/config_flow.py": "\\"\\"\\"Configure every displayed entity through Home Assistant\'s entity pickers.\\"\\"\\"\\nfrom copy import deepcopy\\nimport voluptuous as vol\\n\\nfrom homeassistant import config_entries\\nfrom homeassistant.core import callback\\nfrom homeassistant.helpers import selector\\n\\nfrom .model import DOMAIN, COLORS, DEFAULT_TIMEZONE, default_rows, valid_panel_id\\nfrom .weather_model import DEFAULT_WEATHER_ENTITY, DEFAULT_TEMPERATURE_SENSOR\\n\\n\\ndef panel_schema(values, initial=False):\\n    schema = {}\\n    if initial:\\n        schema[vol.Required(\\"panel_id\\", default=\\"heating\\")] = str\\n    schema[vol.Required(\\"title\\", default=values.get(\\"title\\", \\"Heating\\"))] = vol.All(str, vol.Length(min=1, max=28))\\n    schema[vol.Required(\\"count\\", default=str(values.get(\\"count\\", 6)))] = selector.SelectSelector(\\n        selector.SelectSelectorConfig(options=[\\"4\\", \\"6\\"]))\\n    schema[vol.Required(\\"timezone\\", default=values.get(\\"timezone\\", DEFAULT_TIMEZONE))] = vol.All(str, vol.Length(min=1, max=95))\\n    return vol.Schema(schema)\\n\\n\\ndef row_schema(values):\\n    schema = {vol.Required(\\"enabled\\", default=values.get(\\"enabled\\", True)): bool,\\n              vol.Required(\\"label\\", default=values.get(\\"label\\", \\"\\")): vol.All(str, vol.Length(max=28))}\\n    for name in (\\"entity\\", \\"subtract\\"):\\n        marker = vol.Optional(name, description={\\"suggested_value\\": values.get(name, \\"\\")})\\n        schema[marker] = selector.EntitySelector(selector.EntitySelectorConfig())\\n    schema[vol.Optional(\\"unit\\", default=values.get(\\"unit\\", \\"\\"))] = vol.All(str, vol.Length(max=8))\\n    schema[vol.Required(\\"decimals\\", default=values.get(\\"decimals\\", 1))] = vol.All(vol.Coerce(int), vol.Range(min=0, max=3))\\n    schema[vol.Required(\\"color\\", default=values.get(\\"color\\", \\"cyan\\"))] = selector.SelectSelector(\\n        selector.SelectSelectorConfig(options=[key for key in COLORS if key != \\"muted\\"]))\\n    for name in (\\"warning\\", \\"critical\\"):\\n        schema[vol.Optional(name, description={\\"suggested_value\\": values.get(name)})] = vol.Coerce(float)\\n    return vol.Schema(schema)\\n\\n\\ndef weather_schema(values):\\n    return vol.Schema({\\n        vol.Required(\\"weather_enabled\\", default=values.get(\\"weather_enabled\\", False)): bool,\\n        vol.Optional(\\"weather_entity\\", description={\\"suggested_value\\": values.get(\\"weather_entity\\") or DEFAULT_WEATHER_ENTITY}):\\n            selector.EntitySelector(selector.EntitySelectorConfig(domain=\\"weather\\")),\\n        vol.Optional(\\"temperature_sensor\\", description={\\n            \\"suggested_value\\": values.get(\\"temperature_sensor\\", DEFAULT_TEMPERATURE_SENSOR)}):\\n            selector.EntitySelector(selector.EntitySelectorConfig(domain=\\"sensor\\")),\\n        vol.Required(\\"page_seconds\\", default=values.get(\\"page_seconds\\", 20)):\\n            vol.All(vol.Coerce(int), vol.Range(min=10, max=300)),\\n    })\\n\\n\\nclass PanelConfigFlow(config_entries.ConfigFlow, domain=DOMAIN):\\n    VERSION = 1\\n\\n    async def async_step_user(self, user_input=None):\\n        errors = {}\\n        if user_input:\\n            panel_id = user_input[\\"panel_id\\"].strip()\\n            if not valid_panel_id(panel_id):\\n                errors[\\"panel_id\\"] = \\"invalid_panel_id\\"\\n            else:\\n                await self.async_set_unique_id(panel_id)\\n                self._abort_if_unique_id_configured()\\n                data = dict(user_input, panel_id=panel_id, rows=default_rows())\\n                data[\\"count\\"] = int(data[\\"count\\"])\\n                return self.async_create_entry(title=data[\\"title\\"], data=data)\\n        return self.async_show_form(step_id=\\"user\\", data_schema=panel_schema(user_input or {}, True), errors=errors)\\n\\n    @staticmethod\\n    @callback\\n    def async_get_options_flow(config_entry):\\n        return PanelOptionsFlow()\\n\\n\\nclass PanelOptionsFlow(config_entries.OptionsFlow):\\n    def __init__(self):\\n        self._slot = 0\\n\\n    @property\\n    def settings(self):\\n        return self.config_entry.options or self.config_entry.data\\n\\n    async def async_step_init(self, user_input=None):\\n        return self.async_show_menu(step_id=\\"init\\", menu_options=[\\"panel\\", \\"weather\\", *[f\\"slot_{i}\\" for i in range(1, 7)]])\\n\\n    async def async_step_panel(self, user_input=None):\\n        if user_input:\\n            data = deepcopy(dict(self.settings))\\n            data.update(user_input, count=int(user_input[\\"count\\"]))\\n            return self.async_create_entry(title=\\"\\", data=data)\\n        return self.async_show_form(step_id=\\"panel\\", data_schema=panel_schema(self.settings))\\n\\n    async def async_step_weather(self, user_input=None):\\n        if user_input is not None:\\n            if user_input.get(\\"weather_enabled\\") and not user_input.get(\\"weather_entity\\"):\\n                return self.async_show_form(step_id=\\"weather\\", data_schema=weather_schema(user_input),\\n                                            errors={\\"base\\": \\"weather_required\\"})\\n            data = deepcopy(dict(self.settings))\\n            data.update(user_input)\\n            data[\\"temperature_sensor\\"] = user_input.get(\\"temperature_sensor\\", \\"\\")\\n            return self.async_create_entry(title=\\"\\", data=data)\\n        return self.async_show_form(step_id=\\"weather\\", data_schema=weather_schema(self.settings))\\n\\n    async def async_step_row(self, user_input=None):\\n        data = deepcopy(dict(self.settings))\\n        rows = data.get(\\"rows\\", default_rows())\\n        if user_input is not None:\\n            rows[self._slot] = user_input\\n            data[\\"rows\\"] = rows\\n            return self.async_create_entry(title=\\"\\", data=data)\\n        return self.async_show_form(step_id=\\"row\\", data_schema=row_schema(rows[self._slot]),\\n                                    description_placeholders={\\"slot\\": str(self._slot + 1)})\\n\\n    async def async_step_slot_1(self, user_input=None):\\n        self._slot = 0\\n        return await self.async_step_row()\\n\\n    async def async_step_slot_2(self, user_input=None):\\n        self._slot = 1\\n        return await self.async_step_row()\\n\\n    async def async_step_slot_3(self, user_input=None):\\n        self._slot = 2\\n        return await self.async_step_row()\\n\\n    async def async_step_slot_4(self, user_input=None):\\n        self._slot = 3\\n        return await self.async_step_row()\\n\\n    async def async_step_slot_5(self, user_input=None):\\n        self._slot = 4\\n        return await self.async_step_row()\\n\\n    async def async_step_slot_6(self, user_input=None):\\n        self._slot = 5\\n        return await self.async_step_row()\\n", "custom_components/ha_panel/manifest.json": "{\\n  \\"domain\\": \\"ha_panel\\",\\n  \\"name\\": \\"HA Panel\\",\\n  \\"version\\": \\"1.2.0\\",\\n  \\"config_flow\\": true,\\n  \\"dependencies\\": [\\n    \\"mqtt\\",\\n    \\"weather\\"\\n  ],\\n  \\"codeowners\\": [],\\n  \\"documentation\\": \\"https://github.com/D-C-Blackwell/heating-flow-monitoring\\",\\n  \\"iot_class\\": \\"local_push\\",\\n  \\"issue_tracker\\": \\"https://github.com/D-C-Blackwell/heating-flow-monitoring/issues\\"\\n}\\n", "custom_components/ha_panel/model.py": "\\"\\"\\"Pure formatting and panel calculations, shared by all display consumers.\\"\\"\\"\\nfrom math import isfinite\\nimport re\\n\\nDOMAIN = \\"ha_panel\\"\\nDEFAULT_TIMEZONE = \\"GMT0BST,M3.5.0/1,M10.5.0\\"\\nCOLORS = {\\"cyan\\": \\"#65d7ff\\", \\"green\\": \\"#65d58a\\", \\"amber\\": \\"#ffc857\\",\\n          \\"red\\": \\"#ff6666\\", \\"white\\": \\"#edf4ff\\", \\"muted\\": \\"#98a7b9\\"}\\nDEFAULT_LABELS = [\\"Boiler flow\\", \\"Hot press flow\\", \\"Boiler return\\", \\"Hot press rtn\\",\\n                  \\"Boiler A-B\\", \\"Hot press delta\\"]\\n\\n\\ndef valid_panel_id(value):\\n    return bool(re.fullmatch(r\\"[a-z0-9_-]{1,24}\\", value))\\n\\n\\ndef default_rows():\\n    # Sources are deliberately empty: select your own entities in Configure.\\n    return [{\\"enabled\\": True, \\"label\\": label, \\"entity\\": \\"\\", \\"subtract\\": \\"\\",\\n             \\"unit\\": \\"\\", \\"decimals\\": 1, \\"color\\": \\"cyan\\"}\\n            for label in DEFAULT_LABELS]\\n\\n\\n\\ndef finite_number(value):\\n    try:\\n        number = float(value)\\n        return number if isfinite(number) else None\\n    except (TypeError, ValueError):\\n        return None\\n\\n\\ndef render_row(config, get_state):\\n    \\"\\"\\"Keep unknown and incompatible readings explicit, including delta operands.\\"\\"\\"\\n    source_id = config.get(\\"entity\\", \\"\\")\\n    source = get_state(source_id) if source_id else None\\n    label = config.get(\\"label\\") or (source.name if source else \\"Choose entity\\")\\n    unit = config.get(\\"unit\\") or (source.attributes.get(\\"unit_of_measurement\\", \\"\\") if source else \\"\\")\\n    unit = unit or \\"\\"\\n    row = {\\"label\\": label[:28], \\"value\\": \\"--\\", \\"unit\\": str(unit)[:8],\\n           \\"color\\": COLORS[\\"muted\\"], \\"entity\\": source_id, \\"available\\": False}\\n    if not source or source.state in (\\"unknown\\", \\"unavailable\\"):\\n        return row\\n\\n    value = finite_number(source.state)\\n    subtract_id = config.get(\\"subtract\\", \\"\\")\\n    if subtract_id:\\n        other = get_state(subtract_id)\\n        other_value = finite_number(other.state) if other else None\\n        if value is None or other_value is None:\\n            return row\\n        source_unit = source.attributes.get(\\"unit_of_measurement\\", \\"\\")\\n        other_unit = other.attributes.get(\\"unit_of_measurement\\", \\"\\")\\n        if source_unit != other_unit:\\n            row[\\"value\\"] = \\"Unit mismatch\\"\\n            return row\\n        value -= other_value\\n\\n    color = COLORS.get(config.get(\\"color\\", \\"cyan\\"), COLORS[\\"cyan\\"])\\n    if value is not None:\\n        decimals = max(0, min(3, int(config.get(\\"decimals\\", 1))))\\n        # Suppress a displayed negative zero after rounding.\\n        value = 0.0 if abs(value) < 0.5 * 10 ** -decimals else value\\n        text = f\\"{value:.{decimals}f}\\"\\n        if len(text) > 12:\\n            text = f\\"{value:.4g}\\"\\n        warning = finite_number(config.get(\\"warning\\"))\\n        critical = finite_number(config.get(\\"critical\\"))\\n        if warning is not None and value >= warning:\\n            color = COLORS[\\"amber\\"]\\n        if critical is not None and value >= critical:\\n            color = COLORS[\\"red\\"]\\n    else:\\n        text = source.state[:18]\\n        if text == \\"on\\" and source_id.startswith(\\"binary_sensor.\\"):\\n            text, color = \\"ON\\", COLORS[\\"red\\"]\\n        elif text == \\"off\\" and source_id.startswith(\\"binary_sensor.\\"):\\n            text, color = \\"OFF\\", COLORS[\\"green\\"]\\n    row.update(value=text, color=color, available=True)\\n    return row\\n\\n\\ndef display_payload(value):\\n    \\"\\"\\"Use the TFT\'s supported character set on the wire, keeping HA labels intact.\\"\\"\\"\\n    if isinstance(value, str):\\n        return \\"\\".join(character if 32 <= ord(character) < 127 or character == \\"\\\\u00b0\\" else \\"?\\"\\n                       for character in value)\\n    if isinstance(value, list):\\n        return [display_payload(item) for item in value]\\n    if isinstance(value, dict):\\n        return {key: display_payload(item) for key, item in value.items()}\\n    return value\\n", "custom_components/ha_panel/sensor.py": "\\"\\"\\"Render at the server and push retained MQTT snapshots, even with no browser open.\\"\\"\\"\\nimport asyncio\\nfrom datetime import timedelta\\nimport json\\nimport logging\\nimport time\\n\\nfrom homeassistant.components import mqtt\\nfrom homeassistant.components.sensor import SensorEntity\\nfrom homeassistant.components.weather import WeatherEntityFeature\\nfrom homeassistant.core import callback\\nfrom homeassistant.exceptions import HomeAssistantError\\nfrom homeassistant.helpers.event import async_call_later, async_track_state_change_event, async_track_time_interval\\n\\nfrom .model import DOMAIN, DEFAULT_TIMEZONE, default_rows, render_row, display_payload\\nfrom .weather_model import DEFAULT_WEATHER_ENTITY, DEFAULT_TEMPERATURE_SENSOR, build_weather\\n\\n_LOGGER = logging.getLogger(__name__)\\n\\n\\nasync def async_setup_entry(hass, entry, async_add_entities):\\n    async_add_entities([PanelSensor(entry)])\\n\\n\\nclass PanelSensor(SensorEntity):\\n    _attr_should_poll = False\\n    _attr_icon = \\"mdi:monitor-dashboard\\"\\n\\n    def __init__(self, entry):\\n        self.entry = entry\\n        self.settings = entry.options or entry.data\\n        self.panel_id = entry.data[\\"panel_id\\"]\\n        self._attr_unique_id = f\\"{self.panel_id}_panel\\"\\n        self._attr_name = f\\"HA Panel {self.panel_id}\\"\\n        self._attr_native_value = \\"empty\\"\\n        self._attr_extra_state_attributes = {}\\n        self._lock = asyncio.Lock()\\n        self._cancel_pending = None\\n        self._closing = False\\n        self._refresh_again = False\\n        self._connected = False\\n        self._forecast_task = None\\n        self._forecasts = []\\n        self._forecast_kind = \\"hourly\\"\\n        self._forecast_updated = 0\\n        self._forecast_attempted = 0\\n        self._weather_enabled = self.settings.get(\\"weather_enabled\\", False)\\n        self._weather_entity = self.settings.get(\\"weather_entity\\") or DEFAULT_WEATHER_ENTITY\\n        self._temperature_sensor = self.settings.get(\\"temperature_sensor\\", DEFAULT_TEMPERATURE_SENSOR)\\n        self._attr_device_info = {\\"identifiers\\": {(DOMAIN, self.panel_id)},\\n                                  \\"name\\": self.settings.get(\\"title\\", \\"HA Panel\\"),\\n                                  \\"manufacturer\\": \\"Custom\\", \\"model\\": \\"ESP8266 ILI9341 panel\\"}\\n\\n    async def async_added_to_hass(self):\\n        await super().async_added_to_hass()\\n        entities = {row.get(key) for row in self.settings.get(\\"rows\\", [])\\n                    for key in (\\"entity\\", \\"subtract\\") if row.get(key)}\\n        if self._weather_enabled:\\n            entities.add(self._weather_entity)\\n            if self._temperature_sensor:\\n                entities.add(self._temperature_sensor)\\n            self.async_on_remove(async_track_time_interval(\\n                self.hass, self._forecast_tick, timedelta(minutes=15)))\\n        if entities:\\n            self.async_on_remove(async_track_state_change_event(self.hass, entities, self._queue))\\n        self.async_on_remove(async_track_time_interval(self.hass, self._queue, timedelta(seconds=30)))\\n        self.async_on_remove(await mqtt.async_subscribe(\\n            self.hass, f\\"ha_panel/{self.panel_id}/availability\\", self._status))\\n        await self._refresh()\\n        self._schedule_forecast()\\n\\n    @callback\\n    def _status(self, message):\\n        self._connected = message.payload == \\"online\\"\\n        self._queue(None)\\n\\n    @callback\\n    def _queue(self, _event):\\n        if self._closing:\\n            return\\n        if self._weather_enabled and not self._forecasts and time.monotonic() - self._forecast_attempted > 60:\\n            self._schedule_forecast()\\n        if self._cancel_pending:\\n            return\\n        self._cancel_pending = async_call_later(self.hass, 0.25, self._run)\\n\\n    @callback\\n    def _run(self, _now):\\n        self._cancel_pending = None\\n        self.entry.async_create_task(self.hass, self._refresh(), \\"Refresh HA panel\\")\\n\\n    @callback\\n    def _forecast_tick(self, _now):\\n        self._schedule_forecast()\\n\\n    @callback\\n    def _schedule_forecast(self):\\n        if self._closing or not self._weather_enabled:\\n            return\\n        if self._forecast_task and not self._forecast_task.done():\\n            return\\n        self._forecast_task = self.entry.async_create_task(\\n            self.hass, self._fetch_forecast(), \\"Fetch panel weather forecast\\")\\n\\n    async def _fetch_forecast(self):\\n        self._forecast_attempted = time.monotonic()\\n        state = self.hass.states.get(self._weather_entity)\\n        if not state or state.state in (\\"unavailable\\", \\"unknown\\"):\\n            return\\n        features = state.attributes.get(\\"supported_features\\", 0)\\n        choices = (\\n            (\\"hourly\\", WeatherEntityFeature.FORECAST_HOURLY),\\n            (\\"daily\\", WeatherEntityFeature.FORECAST_DAILY),\\n            (\\"twice_daily\\", WeatherEntityFeature.FORECAST_TWICE_DAILY),\\n        )\\n        kind = next((name for name, flag in choices if features & flag), None)\\n        if kind is None:\\n            return\\n        try:\\n            async with asyncio.timeout(6):\\n                response = await self.hass.services.async_call(\\n                    \\"weather\\", \\"get_forecasts\\",\\n                    {\\"entity_id\\": self._weather_entity, \\"type\\": kind},\\n                    blocking=True, return_response=True)\\n            forecast = (response or {}).get(self._weather_entity, {}).get(\\"forecast\\", [])\\n            self._forecasts = [entry for entry in forecast[:96] if isinstance(entry, dict)]\\n            self._forecast_kind = kind\\n            self._forecast_updated = time.monotonic()\\n        except (HomeAssistantError, TimeoutError, TypeError) as error:\\n            _LOGGER.warning(\\"Weather forecast unavailable for panel %s: %s\\", self.panel_id, error)\\n        finally:\\n            if not self._closing:\\n                self._queue(None)\\n\\n    async def _refresh(self):\\n        if self._lock.locked():\\n            self._refresh_again = True\\n            return\\n        async with self._lock:\\n            if self._closing:\\n                return\\n            count = int(self.settings.get(\\"count\\", 6))\\n            rows = [render_row(row, self.hass.states.get)\\n                    for row in self.settings.get(\\"rows\\", default_rows())[:count]\\n                    if row.get(\\"enabled\\", True)]\\n            title = self.settings.get(\\"title\\", \\"Heating\\")[:28]\\n            weather = {\\"enabled\\": False}\\n            if self._weather_enabled:\\n                weather = build_weather(\\n                    self.hass.states.get(self._weather_entity),\\n                    self.hass.states.get(self._temperature_sensor) if self._temperature_sensor else None,\\n                    self._forecasts, self._forecast_kind, time.time(),\\n                    bool(self._forecast_updated and time.monotonic() - self._forecast_updated < 3600))\\n            page_seconds = max(10, min(300, int(self.settings.get(\\"page_seconds\\", 20))))\\n            attributes = {\\"weather\\": weather, \\"page_seconds\\": page_seconds, \\"title\\": title, \\"rows\\": rows, \\"panel_id\\": self.panel_id,\\n                          \\"screen_online\\": self._connected, \\"slots\\": count}\\n            self._attr_native_value = \\"ready\\" if rows and all(row[\\"available\\"] for row in rows) else \\"incomplete\\" if rows else \\"empty\\"\\n            if self._attr_extra_state_attributes != attributes:\\n                self._attr_extra_state_attributes = attributes\\n                self.async_write_ha_state()\\n            payload = {\\"weather\\": weather, \\"page_seconds\\": page_seconds, \\"v\\": 1, \\"title\\": title, \\"rows\\": [{key: row[key] for key in (\\"label\\", \\"value\\", \\"unit\\", \\"color\\", \\"entity\\")} for row in rows], \\"slots\\": count,\\n                       \\"timezone\\": self.settings.get(\\"timezone\\", DEFAULT_TIMEZONE),\\n                       \\"updated\\": int(time.time())}\\n            try:\\n                await mqtt.async_publish(self.hass, f\\"ha_panel/{self.panel_id}/state\\",\\n                                         json.dumps(display_payload(payload), ensure_ascii=True, separators=(\\",\\", \\":\\")), qos=1, retain=True)\\n            except HomeAssistantError as error:\\n                _LOGGER.warning(\\"Panel %s could not publish; retrying on the next heartbeat: %s\\", self.panel_id, error)\\n            if self._refresh_again and not self._closing:\\n                self._refresh_again = False\\n                self._queue(None)\\n\\n    async def async_will_remove_from_hass(self):\\n        self._closing = True\\n        if self._forecast_task and not self._forecast_task.done():\\n            self._forecast_task.cancel()\\n            await asyncio.gather(self._forecast_task, return_exceptions=True)\\n        if self._cancel_pending:\\n            self._cancel_pending()\\n        async with self._lock:\\n            pass\\n        await super().async_will_remove_from_hass()\\n", "custom_components/ha_panel/strings.json": "{\\n  \\"title\\": \\"HA Panel\\",\\n  \\"config\\": {\\n    \\"step\\": {\\n      \\"user\\": {\\n        \\"title\\": \\"Add a display panel\\",\\n        \\"description\\": \\"Choose a panel ID matching the display setup. After adding the integration, use Configure to select your entities.\\",\\n        \\"data\\": {\\n          \\"panel_id\\": \\"Panel ID\\",\\n          \\"title\\": \\"Screen title\\",\\n          \\"count\\": \\"Number of readings\\",\\n          \\"timezone\\": \\"POSIX timezone\\"\\n        }\\n      }\\n    },\\n    \\"error\\": {\\n      \\"invalid_panel_id\\": \\"Use 1\\\\u201324 lowercase letters, digits, hyphens or underscores.\\"\\n    },\\n    \\"abort\\": {\\n      \\"already_configured\\": \\"This panel ID is already configured.\\"\\n    }\\n  },\\n  \\"options\\": {\\n    \\"step\\": {\\n      \\"init\\": {\\n        \\"title\\": \\"Edit the display\\",\\n        \\"description\\": \\"Changes are sent to the physical display and dashboard card automatically.\\",\\n        \\"menu_options\\": {\\n          \\"panel\\": \\"Screen title, layout and timezone\\",\\n          \\"slot_1\\": \\"Reading 1\\",\\n          \\"slot_2\\": \\"Reading 2\\",\\n          \\"slot_3\\": \\"Reading 3\\",\\n          \\"slot_4\\": \\"Reading 4\\",\\n          \\"slot_5\\": \\"Reading 5\\",\\n          \\"slot_6\\": \\"Reading 6\\",\\n          \\"weather\\": \\"Weather page and page rotation\\"\\n        }\\n      },\\n      \\"panel\\": {\\n        \\"title\\": \\"Screen settings\\",\\n        \\"data\\": {\\n          \\"title\\": \\"Screen title\\",\\n          \\"count\\": \\"Number of readings\\",\\n          \\"timezone\\": \\"POSIX timezone\\"\\n        }\\n      },\\n      \\"row\\": {\\n        \\"title\\": \\"Reading {slot}\\",\\n        \\"description\\": \\"Choose a source. To show a temperature difference, select flow as Source and return as Subtract. Leave Unit override blank to use the source unit. Labels and values also appear on the dashboard.\\",\\n        \\"data\\": {\\n          \\"enabled\\": \\"Show this reading\\",\\n          \\"label\\": \\"Label\\",\\n          \\"entity\\": \\"Source entity\\",\\n          \\"subtract\\": \\"Subtract entity (optional, for delta)\\",\\n          \\"unit\\": \\"Unit override (blank uses source unit)\\",\\n          \\"decimals\\": \\"Decimal places\\",\\n          \\"color\\": \\"Value colour\\",\\n          \\"warning\\": \\"Amber at or above (optional)\\",\\n          \\"critical\\": \\"Red at or above (optional)\\"\\n        }\\n      },\\n      \\"weather\\": {\\n        \\"title\\": \\"Weather page\\",\\n        \\"description\\": \\"The non-touch screen alternates between readings and weather. Select the weather provider and the connected temperature sensor. Forecasts are refreshed every 15 minutes. Rain timing is shown when the provider supports hourly forecasts.\\",\\n        \\"data\\": {\\n          \\"weather_enabled\\": \\"Show the second weather page\\",\\n          \\"weather_entity\\": \\"Weather provider\\",\\n          \\"temperature_sensor\\": \\"Connected temperature sensor (optional)\\",\\n          \\"page_seconds\\": \\"Seconds on each page (10\\\\u2013300)\\"\\n        }\\n      }\\n    },\\n    \\"error\\": {\\n      \\"weather_required\\": \\"Select a weather entity before enabling the weather page.\\"\\n    }\\n  }\\n}\\n", "custom_components/ha_panel/translations/en.json": "{\\n  \\"title\\": \\"HA Panel\\",\\n  \\"config\\": {\\n    \\"step\\": {\\n      \\"user\\": {\\n        \\"title\\": \\"Add a display panel\\",\\n        \\"description\\": \\"Choose a panel ID matching the display setup. After adding the integration, use Configure to select your entities.\\",\\n        \\"data\\": {\\n          \\"panel_id\\": \\"Panel ID\\",\\n          \\"title\\": \\"Screen title\\",\\n          \\"count\\": \\"Number of readings\\",\\n          \\"timezone\\": \\"POSIX timezone\\"\\n        }\\n      }\\n    },\\n    \\"error\\": {\\n      \\"invalid_panel_id\\": \\"Use 1\\\\u201324 lowercase letters, digits, hyphens or underscores.\\"\\n    },\\n    \\"abort\\": {\\n      \\"already_configured\\": \\"This panel ID is already configured.\\"\\n    }\\n  },\\n  \\"options\\": {\\n    \\"step\\": {\\n      \\"init\\": {\\n        \\"title\\": \\"Edit the display\\",\\n        \\"description\\": \\"Changes are sent to the physical display and dashboard card automatically.\\",\\n        \\"menu_options\\": {\\n          \\"panel\\": \\"Screen title, layout and timezone\\",\\n          \\"slot_1\\": \\"Reading 1\\",\\n          \\"slot_2\\": \\"Reading 2\\",\\n          \\"slot_3\\": \\"Reading 3\\",\\n          \\"slot_4\\": \\"Reading 4\\",\\n          \\"slot_5\\": \\"Reading 5\\",\\n          \\"slot_6\\": \\"Reading 6\\",\\n          \\"weather\\": \\"Weather page and page rotation\\"\\n        }\\n      },\\n      \\"panel\\": {\\n        \\"title\\": \\"Screen settings\\",\\n        \\"data\\": {\\n          \\"title\\": \\"Screen title\\",\\n          \\"count\\": \\"Number of readings\\",\\n          \\"timezone\\": \\"POSIX timezone\\"\\n        }\\n      },\\n      \\"row\\": {\\n        \\"title\\": \\"Reading {slot}\\",\\n        \\"description\\": \\"Choose a source. To show a temperature difference, select flow as Source and return as Subtract. Leave Unit override blank to use the source unit. Labels and values also appear on the dashboard.\\",\\n        \\"data\\": {\\n          \\"enabled\\": \\"Show this reading\\",\\n          \\"label\\": \\"Label\\",\\n          \\"entity\\": \\"Source entity\\",\\n          \\"subtract\\": \\"Subtract entity (optional, for delta)\\",\\n          \\"unit\\": \\"Unit override (blank uses source unit)\\",\\n          \\"decimals\\": \\"Decimal places\\",\\n          \\"color\\": \\"Value colour\\",\\n          \\"warning\\": \\"Amber at or above (optional)\\",\\n          \\"critical\\": \\"Red at or above (optional)\\"\\n        }\\n      },\\n      \\"weather\\": {\\n        \\"title\\": \\"Weather page\\",\\n        \\"description\\": \\"The non-touch screen alternates between readings and weather. Select the weather provider and the connected temperature sensor. Forecasts are refreshed every 15 minutes. Rain timing is shown when the provider supports hourly forecasts.\\",\\n        \\"data\\": {\\n          \\"weather_enabled\\": \\"Show the second weather page\\",\\n          \\"weather_entity\\": \\"Weather provider\\",\\n          \\"temperature_sensor\\": \\"Connected temperature sensor (optional)\\",\\n          \\"page_seconds\\": \\"Seconds on each page (10\\\\u2013300)\\"\\n        }\\n      }\\n    },\\n    \\"error\\": {\\n      \\"weather_required\\": \\"Select a weather entity before enabling the weather page.\\"\\n    }\\n  }\\n}\\n", "custom_components/ha_panel/weather_model.py": "\\"\\"\\"Build bounded weather snapshots from Home Assistant states and forecasts.\\"\\"\\"\\nfrom datetime import datetime\\n\\nfrom .model import finite_number\\n\\nDEFAULT_WEATHER_ENTITY = \\"\\"\\nDEFAULT_TEMPERATURE_SENSOR = \\"\\"\\nWET_CONDITIONS = {\\"rainy\\", \\"pouring\\", \\"lightning-rainy\\", \\"snowy-rainy\\"}\\nCONDITIONS = {\\n    \\"clear-night\\": \\"Clear night\\", \\"cloudy\\": \\"Cloudy\\", \\"exceptional\\": \\"Unusual weather\\",\\n    \\"fog\\": \\"Fog\\", \\"hail\\": \\"Hail\\", \\"lightning\\": \\"Thunderstorms\\",\\n    \\"lightning-rainy\\": \\"Thunder and rain\\", \\"partlycloudy\\": \\"Partly cloudy\\",\\n    \\"pouring\\": \\"Heavy rain\\", \\"rainy\\": \\"Rain\\", \\"snowy\\": \\"Snow\\",\\n    \\"snowy-rainy\\": \\"Sleet\\", \\"sunny\\": \\"Sunny\\", \\"windy\\": \\"Windy\\",\\n    \\"windy-variant\\": \\"Windy and cloudy\\",\\n}\\n\\n\\ndef forecast_epoch(value):\\n    try:\\n        parsed = datetime.fromisoformat(str(value).replace(\\"Z\\", \\"+00:00\\"))\\n        if parsed.tzinfo is None:\\n            return None\\n        return int(parsed.timestamp())\\n    except (TypeError, ValueError, OverflowError):\\n        return None\\n\\n\\ndef temperature_text(value):\\n    number = finite_number(value)\\n    if number is None:\\n        return \\"--\\"\\n    return f\\"{number:.1f}\\" if abs(number) < 1000 else f\\"{number:.3g}\\"\\n\\n\\ndef build_weather(weather, sensor, forecasts, kind, now, forecast_fresh):\\n    available = weather is not None and weather.state not in (\\"unknown\\", \\"unavailable\\")\\n    attributes = weather.attributes if available else {}\\n    condition = weather.state if available else \\"unavailable\\"\\n    sensor_available = sensor is not None and sensor.state not in (\\"unknown\\", \\"unavailable\\")\\n    result = {\\n        \\"enabled\\": True,\\n        \\"available\\": available,\\n        \\"condition\\": condition,\\n        \\"condition_text\\": CONDITIONS.get(condition, \\"Weather unavailable\\"),\\n        \\"temperature\\": temperature_text(attributes.get(\\"temperature\\")),\\n        \\"unit\\": attributes.get(\\"temperature_unit\\") or \\"\\",\\n        \\"sensor_label\\": (sensor.name if sensor else \\"Local sensor\\")[:28],\\n        \\"sensor_temperature\\": temperature_text(sensor.state if sensor_available else None),\\n        \\"sensor_unit\\": (sensor.attributes.get(\\"unit_of_measurement\\") or \\"\\") if sensor_available else \\"\\",\\n        \\"forecast_kind\\": kind,\\n        \\"rain_summary\\": \\"Forecast unavailable\\",\\n        \\"rain_probability\\": None,\\n        \\"next_rain\\": 0,\\n        \\"forecast\\": [],\\n    }\\n    if condition in WET_CONDITIONS:\\n        result[\\"rain_summary\\"] = \\"Rain now\\"\\n    if not forecast_fresh:\\n        return result\\n\\n    upcoming = []\\n    for forecast in forecasts:\\n        stamp = forecast_epoch(forecast.get(\\"datetime\\"))\\n        if stamp is None:\\n            continue\\n        # An hourly forecast describes its whole hour. Daily/twice-daily\\n        # entries can start earlier today and still describe current weather.\\n        tolerance = 3600 if kind == \\"hourly\\" else 86400\\n        if stamp < now - tolerance:\\n            continue\\n        if kind != \\"hourly\\":\\n            period = datetime.fromisoformat(str(forecast[\\"datetime\\"]).replace(\\"Z\\", \\"+00:00\\"))\\n            if period.date() < datetime.fromtimestamp(now, period.tzinfo).date():\\n                continue\\n        probability = finite_number(forecast.get(\\"precipitation_probability\\"))\\n        if probability is not None:\\n            probability = round(max(0, min(100, probability)))\\n        upcoming.append({\\n            \\"time\\": stamp,\\n            \\"condition\\": str(forecast.get(\\"condition\\") or \\"unknown\\")[:24],\\n            \\"temperature\\": temperature_text(forecast.get(\\"temperature\\")),\\n            \\"probability\\": probability,\\n            \\"precipitation\\": finite_number(forecast.get(\\"precipitation\\")),\\n        })\\n    upcoming.sort(key=lambda entry: entry[\\"time\\"])\\n    result[\\"forecast\\"] = [\\n        {key: entry[key] for key in (\\"time\\", \\"condition\\", \\"temperature\\", \\"probability\\")}\\n        for entry in upcoming[:3]\\n    ]\\n    horizon = 12 * 3600 if kind == \\"hourly\\" else 24 * 3600\\n    relevant = [entry for entry in upcoming if entry[\\"time\\"] < now + horizon]\\n    if not relevant:\\n        return result\\n    probabilities = [entry[\\"probability\\"] for entry in relevant if entry[\\"probability\\"] is not None]\\n    result[\\"rain_probability\\"] = max(probabilities) if probabilities else None\\n    wet = [\\n        entry for entry in relevant\\n        if entry[\\"condition\\"] not in (\\"snowy\\", \\"hail\\") and (\\n            entry[\\"condition\\"] in WET_CONDITIONS\\n            or (entry[\\"precipitation\\"] is not None and entry[\\"precipitation\\"] > 0)\\n            or (entry[\\"probability\\"] is not None and entry[\\"probability\\"] >= 40))\\n    ]\\n    if wet:\\n        result[\\"next_rain\\"] = next(\\n            (entry[\\"time\\"] for entry in wet if entry[\\"time\\"] > now), 0)\\n    if condition not in WET_CONDITIONS:\\n        has_rain_data = any(\\n            entry[\\"condition\\"] in CONDITIONS or entry[\\"probability\\"] is not None\\n            or entry[\\"precipitation\\"] is not None for entry in relevant)\\n        if not has_rain_data:\\n            return result\\n        if kind == \\"hourly\\":\\n            period = \\"next 12h\\" if relevant[-1][\\"time\\"] >= now + 10 * 3600 else \\"next hours\\"\\n        else:\\n            period = \\"next day\\"\\n        if wet:\\n            confidence = result[\\"rain_probability\\"]\\n            label = \\"Rain likely\\" if confidence is not None and confidence >= 60 else \\"Rain possible\\"\\n            result[\\"rain_summary\\"] = f\\"{label} - {period}\\"\\n        elif any(entry[\\"condition\\"] == \\"snowy\\" for entry in relevant):\\n            result[\\"rain_summary\\"] = f\\"Snow forecast - {period}\\"\\n        elif any(entry[\\"condition\\"] == \\"hail\\" for entry in relevant):\\n            result[\\"rain_summary\\"] = f\\"Hail forecast - {period}\\"\\n        else:\\n            result[\\"rain_summary\\"] = f\\"No rain forecast - {period}\\"\\n    return result\\n", "www/ha-panel-card.js": "class HaPanelCard extends HTMLElement {\\n  static getStubConfig() {\\n    return { entity: \\"sensor.ha_panel_heating\\" };\\n  }\\n\\n  static getConfigElement() {\\n    return document.createElement(\\"ha-panel-card-editor\\");\\n  }\\n\\n  constructor() {\\n    super();\\n    this._page = 0;\\n    this.attachShadow({ mode: \\"open\\" });\\n    this.shadowRoot.innerHTML = `\\n      <style>\\n        :host { display: block; }\\n        ha-card { background: #101b2b; color: #edf4ff; padding: 20px; overflow: hidden; }\\n        header { display: flex; align-items: center; gap: 12px; margin-bottom: 18px; }\\n        h2 { margin: 0; font: 500 22px var(--paper-font-body1_-_font-family, sans-serif); flex: 1; }\\n        button { color: #b8c7d8; border: 0; background: transparent; cursor: pointer; padding: 8px; border-radius: 8px; }\\n        button:hover { background: #223149; }\\n        button:focus-visible { outline: 2px solid #65d7ff; }\\n        .status { color: #98a7b9; font-size: 12px; }\\n        .grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }\\n        .reading { background: #19263a; padding: 16px; border-radius: 12px; min-width: 0; text-align: left; }\\n        .label { color: #a7b5c8; font-size: 13px; margin-bottom: 10px; overflow-wrap: anywhere; }\\n        .number { font-size: clamp(22px, 6vw, 34px); font-variant-numeric: tabular-nums; overflow-wrap: anywhere; }\\n        .unit { font-size: 14px; color: #a7b5c8; margin-left: 6px; }\\n        .pages { display: flex; gap: 8px; margin-bottom: 12px; }\\n        .pages[hidden] { display: none; }\\n        .pages button { border: 1px solid #33445b; padding: 8px 14px; }\\n        .pages button[aria-selected=\\"true\\"] { background: #263f59; color: #65d7ff; }\\n        .forecast { grid-column: 1 / -1; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; }\\n        .forecast .reading { padding: 12px; }\\n        .forecast .number { font-size: 20px; }\\n        .message { color: #a7b5c8; line-height: 1.5; }\\n      </style>\\n      <ha-card>\\n        <header>\\n          <h2></h2><span class=\\"status\\"></span>\\n          <button class=\\"configure\\" title=\\"Configure display entities\\" aria-label=\\"Configure display entities\\">\\n            <ha-icon icon=\\"mdi:cog-outline\\"></ha-icon>\\n          </button>\\n        </header>\\n        <nav class=\\"pages\\" aria-label=\\"Display pages\\" hidden>\\n          <button data-page=\\"0\\" aria-selected=\\"true\\">Readings</button>\\n          <button data-page=\\"1\\" aria-selected=\\"false\\">Weather</button>\\n        </nav>\\n        <div class=\\"grid\\"></div><div class=\\"message\\"></div>\\n      </ha-card>`;\\n    for (const button of this.shadowRoot.querySelectorAll(\\"[data-page]\\")) {\\n      button.addEventListener(\\"click\\", () => {\\n        this._page = Number(button.dataset.page);\\n        this._lastData = \\"\\";\\n        this._render();\\n      });\\n    }\\n    this.shadowRoot.querySelector(\\".configure\\").addEventListener(\\"click\\", () => {\\n      history.pushState(null, \\"\\", \\"/config/integrations/integration/ha_panel\\");\\n      window.dispatchEvent(new Event(\\"location-changed\\"));\\n    });\\n  }\\n\\n  setConfig(config) {\\n    this._config = { ...config };\\n    this._lastData = \\"\\";\\n    this._render();\\n  }\\n\\n  set hass(hass) {\\n    this._hass = hass;\\n    this._render();\\n  }\\n\\n  getCardSize() {\\n    return 5;\\n  }\\n\\n  getGridOptions() {\\n    return { columns: 12, min_columns: 6, rows: \\"auto\\" };\\n  }\\n\\n  _render() {\\n    if (!this._hass || !this._config) return;\\n    const entity = this._config.entity;\\n    const state = this._hass.states[entity];\\n    const data = state?.attributes;\\n    if (!data?.weather?.enabled) this._page = 0;\\n    const fingerprint = JSON.stringify([state?.state, data?.title, data?.rows,\\n                                        data?.screen_online, data?.weather, this._page]);\\n    if (fingerprint === this._lastData) return;\\n    this._lastData = fingerprint;\\n    const root = this.shadowRoot;\\n    root.querySelector(\\"h2\\").textContent = this._page === 1 ? \\"Weather\\" : data?.title || \\"HA Panel\\";\\n    root.querySelector(\\".pages\\").hidden = !data?.weather?.enabled;\\n    for (const button of root.querySelectorAll(\\"[data-page]\\")) {\\n      button.setAttribute(\\"aria-selected\\", String(Number(button.dataset.page) === this._page));\\n    }\\n    root.querySelector(\\".status\\").textContent = data?.panel_id\\n      ? (data.screen_online ? \\"Screen online\\" : \\"Screen offline\\") : \\"\\";\\n    const grid = root.querySelector(\\".grid\\");\\n    grid.replaceChildren();\\n    const message = root.querySelector(\\".message\\");\\n    if (!state || !data?.panel_id) {\\n      message.textContent = \\"Choose the HA Panel sensor in this card\'s settings.\\";\\n      return;\\n    }\\n    if ([\\"unavailable\\", \\"unknown\\"].includes(state.state)) {\\n      message.textContent = \\"The Home Assistant panel integration is unavailable.\\";\\n      return;\\n    }\\n    if (this._page === 1) {\\n      message.textContent = \\"\\";\\n      this._renderWeather(grid, data.weather);\\n      return;\\n    }\\n    message.textContent = data.rows?.length ? \\"\\" : \\"Use the settings button to add readings.\\";\\n    for (const row of data.rows || []) {\\n      const cell = document.createElement(row.entity ? \\"button\\" : \\"div\\");\\n      cell.className = \\"reading\\";\\n      const label = document.createElement(\\"div\\");\\n      label.className = \\"label\\";\\n      label.textContent = row.label;\\n      const number = document.createElement(\\"span\\");\\n      number.className = \\"number\\";\\n      number.textContent = row.value;\\n      number.style.color = /^#[0-9a-f]{6}$/i.test(row.color) ? row.color : \\"#65d7ff\\";\\n      const unit = document.createElement(\\"span\\");\\n      unit.className = \\"unit\\";\\n      unit.textContent = row.unit;\\n      cell.append(label, number, unit);\\n      if (row.entity) {\\n        cell.setAttribute(\\"aria-label\\", row.label + \\" \\" + row.value + \\" \\" + row.unit);\\n        cell.addEventListener(\\"click\\", () => this.dispatchEvent(new CustomEvent(\\"hass-more-info\\", {\\n          detail: { entityId: row.entity }, bubbles: true, composed: true,\\n        })));\\n      }\\n      grid.append(cell);\\n    }\\n  }\\n  _weatherCell(labelText, valueText, unitText = \\"\\") {\\n    const cell = document.createElement(\\"div\\");\\n    cell.className = \\"reading\\";\\n    const label = document.createElement(\\"div\\");\\n    label.className = \\"label\\";\\n    label.textContent = labelText;\\n    const value = document.createElement(\\"span\\");\\n    value.className = \\"number\\";\\n    value.textContent = valueText;\\n    value.style.color = \\"#65d7ff\\";\\n    const unit = document.createElement(\\"span\\");\\n    unit.className = \\"unit\\";\\n    unit.textContent = unitText;\\n    cell.append(label, value, unit);\\n    return cell;\\n  }\\n\\n  _renderWeather(grid, weather) {\\n    grid.append(\\n      this._weatherCell(weather.condition_text, weather.temperature, weather.unit),\\n      this._weatherCell(\\"Local sensor\\", weather.sensor_temperature, weather.sensor_unit),\\n    );\\n    const chance = weather.rain_probability == null ? \\"Chance not provided\\" : weather.rain_probability + \\"% chance\\";\\n    const rain = this._weatherCell(weather.rain_summary, chance);\\n    rain.style.gridColumn = \\"1 / -1\\";\\n    rain.querySelector(\\".number\\").style.fontSize = \\"20px\\";\\n    grid.append(rain);\\n    const forecasts = document.createElement(\\"div\\");\\n    forecasts.className = \\"forecast\\";\\n    const formatter = new Intl.DateTimeFormat(this._hass.locale?.language || \\"en\\",\\n      weather.forecast_kind === \\"hourly\\"\\n        ? { hour: \\"2-digit\\", minute: \\"2-digit\\", timeZone: this._hass.config.time_zone }\\n        : { weekday: \\"short\\", day: \\"numeric\\", timeZone: this._hass.config.time_zone });\\n    for (const entry of weather.forecast || []) {\\n      const cell = this._weatherCell(\\n        formatter.format(new Date(entry.time * 1000)), entry.temperature, weather.unit);\\n      const condition = document.createElement(\\"div\\");\\n      condition.className = \\"label\\";\\n      condition.textContent = entry.condition.replaceAll(\\"-\\", \\" \\") +\\n        (entry.probability == null ? \\"\\" : \\" \\u00c2\\u00b7 \\" + entry.probability + \\"%\\");\\n      cell.append(condition);\\n      forecasts.append(cell);\\n    }\\n    grid.append(forecasts);\\n  }\\n\\n}\\n\\nclass HaPanelCardEditor extends HTMLElement {\\n  setConfig(config) {\\n    this._config = { ...config };\\n    this._render();\\n  }\\n\\n  set hass(hass) {\\n    this._hass = hass;\\n    this._render();\\n  }\\n\\n  _render() {\\n    if (!this._config || !this._hass) return;\\n    if (!this._form) {\\n      this._form = document.createElement(\\"ha-form\\");\\n      this._form.schema = [{\\n        name: \\"entity\\", required: true,\\n        selector: { entity: { domain: \\"sensor\\" } },\\n      }];\\n      this._form.computeLabel = () => \\"HA Panel sensor\\";\\n      this._form.addEventListener(\\"value-changed\\", (event) => {\\n        this._config = { ...this._config, ...event.detail.value };\\n        this.dispatchEvent(new CustomEvent(\\"config-changed\\", {\\n          detail: { config: this._config }, bubbles: true, composed: true,\\n        }));\\n      });\\n      this.append(this._form);\\n    }\\n    this._form.hass = this._hass;\\n    this._form.data = this._config;\\n  }\\n}\\n\\ncustomElements.define(\\"ha-panel-card\\", HaPanelCard);\\ncustomElements.define(\\"ha-panel-card-editor\\", HaPanelCardEditor);\\nwindow.customCards = window.customCards || [];\\nwindow.customCards.push({\\n  type: \\"ha-panel-card\\",\\n  name: \\"HA Panel\\",\\n  description: \\"The same readings as your configurable ESP8266 screen.\\",\\n  preview: true,\\n});\\n"}')

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--config", type=Path, help="Home Assistant configuration directory")
    args = parser.parse_args()
    candidates = [args.config] if args.config else [Path("/config"), Path("/homeassistant")]
    target = next((path.resolve() for path in candidates if path and (path / "configuration.yaml").is_file()), None)
    if target is None:
        parser.error("Configuration folder not found. Pass --config followed by its path.")
    backup = target / ".ha-panel-backups" / ("ha-panel-" + datetime.now().strftime("%Y%m%d-%H%M%S-%f"))
    for name, content in FILES.items():
        path = target / name
        path.parent.mkdir(parents=True, exist_ok=True)
        if path.exists():
            saved = backup / name
            saved.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(path, saved)
        temporary = path.with_name(path.name + ".ha-panel-new")
        temporary.write_text(content, encoding="utf-8")
        os.replace(temporary, path)
        print("Installed", name)
    print("Restart Home Assistant, then add HA Panel in Settings > Devices & services.")
    print("Add /local/ha-panel-card.js?v=3 as a JavaScript module dashboard resource.")

if __name__ == "__main__":
    main()
